namespace CheckoutPricing.Domain;

public static class LoyaltyDiscount
{
    private const int MaximumRatePoints = 10;

    public static int AmountFor(int subtotalCents, LoyaltyTier tier)
    {
        var rate = Math.Min(BaseRatePoints(tier) + BandBonusPoints(subtotalCents), MaximumRatePoints);
        return (int)((long)subtotalCents * rate / 100);
    }

    private static int BaseRatePoints(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Green => 5,
        LoyaltyTier.Gold => 7,
        LoyaltyTier.Platinum => 9,
        _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, null),
    };

    private static int BandBonusPoints(int subtotalCents) => subtotalCents switch
    {
        >= 20_000 => 3,
        >= 5_000 => 1,
        _ => 0,
    };
}
